INSERT INTO collections (slug,display_name,owner_id,data,status,created_at,updated_at) VALUES ('emotions','Emotions',NULL,'{"slug":"emotions","id":"emotions","displayName":"Emotions","name":"Emotions","author":"Moll","creator":"Moll","version":"3.2","synopsis":"A script around Minions, this time they are less about causing chaos and misinformation. This time its their task to figure out, are shown actual Love or is it just Hope someone has laid out for them. Figure out if you have someone else like you out there, and if you should turn on your demon, while the demon might be trying to lead you on the wrong path. This script isn''t only built around the evil team lying, the good team is heavily encouraged to lie to avoid these evils & to make out something they really shouldn''t have.\n\nMaybe you have a friend who needs to travel, but its usually terribly unbalanced in teensyvilles, not to worry. You can come into the town as Depression, and lead the town through a ride of emotions.","logo":"https://user-images.klutzbanana.com/vcdkz8z8y7ofadquxvm0viej.png","almanac":"https://klutzbanana.com/scripts/e5govpsx4u/Emotions%20by%20Moll","match":["emotions"],"include":["fear","guilt","anxiety","anger","sadness","grief","disappointment","boredom","excitement","gratitude","happiness","love","hope","faith","depression","the-spiral"],"exclude":[],"order":["fear","guilt","anxiety","anger","sadness","grief","disappointment","boredom","excitement","gratitude","happiness","love","hope","faith","depression","the-spiral"],"curata":false,"customBoxes":[{"title":"Thanks","content":"Thanks to the people who helped a lot with the playtesting of this; special thanks to Swampert, Lucifer, Wildheart, Syddanus, Jasper, Nicklas, Hobbe, Aki & Audeeophile for many long nights."}]}','published',datetime('now'),datetime('now'));
